document.querySelectorAll('.dp').forEach(box => {
  const text = box.querySelector('input:not(.dp__native)'), native = box.querySelector('.dp__native');
  const button = box.querySelector('button'), error = box.nextElementSibling;
  const valid = v => {
    const m = /^(\d{2})\/(\d{2})\/(\d{4})$/.exec(v); if (!m) return false;
    const d = new Date(+m[3], +m[1] - 1, +m[2]); return d.getMonth() === +m[1] - 1 && d.getDate() === +m[2];
  };
  const flag = bad => { text.setAttribute('aria-invalid', String(bad)); if (error) error.hidden = !bad; };
  text.addEventListener('input', () => {
    const d = text.value.replace(/\D/g, '').slice(0, 8);
    text.value = d.length > 4 ? d.slice(0, 2) + '/' + d.slice(2, 4) + '/' + d.slice(4) : d.length > 2 ? d.slice(0, 2) + '/' + d.slice(2) : d;
    if (text.getAttribute('aria-invalid') === 'true' && valid(text.value)) flag(false);
  });
  text.addEventListener('blur', () => { if (text.value) flag(!valid(text.value)); else flag(false); });
  button.addEventListener('click', () => { if (native.showPicker) native.showPicker(); else native.focus(); });
  native.addEventListener('change', () => {
    const [y, m, d] = native.value.split('-'); if (y) { text.value = m + '/' + d + '/' + y; flag(false); text.focus(); }
  });
});
